LEVELS = ("A0", "A1", "A2", "B1", "B2")


def q(kind, prompt, answers, explanation, options=()):
    return {"kind": kind, "prompt": prompt, "answers": list(answers),
            "explanation_vi": explanation, "options": list(options)}


